// Mục 3.7 & 3.9: Không lưu dữ liệu Simulation, chỉ lưu mẫu cảm biến mỗi 60 giây
const p = msg.payload;
if (!p || p.is_simulation === true) return null;

const nowMs = Date.now();
const deviceId = p.device_id || 'esp32_01';
const lastSavedKey = `last_sample_${deviceId}`;
const lastSavedMs = flow.get(lastSavedKey) || 0;
const intervalMs = 60000;

if (nowMs - lastSavedMs < intervalMs) {
    return null; // Chưa đủ 60s -> chỉ hiển thị Dashboard, không ghi Firestore
}

flow.set(lastSavedKey, nowMs);
const s = p.sensors || {};
const act = p.actuators || {};
const dry = p.drying || {};
const tsMs = (p.time_synced && p.timestamp > 1700000000) ? p.timestamp * 1000 : nowMs;

msg.collection = 'sensor_samples';
msg.docId = `SMP_${deviceId}_${tsMs}`;
msg.payload = {
    sample_id: msg.docId,
    group_id: p.group_id || 'G21_24C11',
    device_id: deviceId,
    is_simulation: false,
    timestamp_ms: tsMs,
    recorded_at_iso: new Date(tsMs).toISOString(),
    time_synced: Boolean(p.time_synced),
    dht_valid: Boolean(s.dht_valid),
    temperature_c: s.dht_valid ? Number(s.temperature_c) : null,
    humidity_pct: s.dht_valid ? Number(s.humidity_pct) : null,
    wet_percent: Number(s.wet_percent || 0),
    wet_label: s.wet_label || 'DRY',
    wet_text_vi: s.wet_text_vi || 'Khô',
    light_percent: Number(s.light_percent || 0),
    is_dark: Boolean(s.is_dark),
    rod_state: act.rod_state || 'RETRACTED',
    control_mode: act.control_mode || 'AUTO',
    batch_id: dry.batch_id || null,
    total_drying_sec: Number(dry.total_drying_sec || 0)
};

// Lưu thêm vào mảng lịch sử 24h trong context để phục vụ truy vấn nhanh W19
const hist = flow.get('sensor_samples_24h') || [];
hist.push(msg.payload);
const cutoff = nowMs - 24 * 3600 * 1000;
flow.set('sensor_samples_24h', hist.filter(x => x.timestamp_ms >= cutoff).slice(-1440));

return msg;

const p = msg.payload;
if (!p || p.is_simulation === true) return null;

const nowMs = Date.now();
const docId = `${p.batch_id}_S${String(p.session_id || 0).padStart(3, '0')}`;
const record = {
    doc_id: docId,
    batch_id: p.batch_id,
    session_id: Number(p.session_id || 0),
    device_id: p.device_id || 'esp32_01',
    event_type: p.event_type,
    start_epoch: p.start_epoch,
    end_epoch: p.end_epoch,
    time_synced: Boolean(p.time_synced),
    duration_sec: Number(p.session_duration_sec || 0),
    batch_total_drying_sec: Number(p.batch_total_drying_sec || 0),
    formatted_batch_total: p.formatted_batch_total || '00:00:00',
    trigger_mode: p.trigger_mode || 'AUTO',
    retract_reason: p.reason || 'NONE',
    retract_reason_vi: p.reason_vi || '',
    interrupted: Boolean(p.interrupted),
    updated_at_ms: nowMs
};

const sessions = flow.get('drying_sessions_24h') || [];
const idx = sessions.findIndex(s => s.doc_id === docId);
if (idx >= 0) sessions[idx] = record; else sessions.unshift(record);
flow.set('drying_sessions_24h', sessions.slice(0, 100));

msg.collection = 'drying_sessions';
msg.docId = docId;
msg.payload = record;
return msg;

// Output 1: PushSafer HTTP request
// Output 2: Email SMTP node
// Output 3: Lưu sự kiện vào Firestore events
const p = msg.payload;
if (!p || p.is_simulation === true) return [null, null, null];

const nowMs = Date.now();
const eventCode = p.event_code || 'UNKNOWN';
const cooldownKey = `cd_${p.device_id || 'esp32_01'}_${eventCode}`;
const lastSent = flow.get(cooldownKey) || 0;
const cooldownMs = 15 * 60 * 1000; // 15 phút chống gửi lặp

const events = flow.get('events_24h') || [];
events.unshift({ ...p, received_at_ms: nowMs });
flow.set('events_24h', events.slice(0, 100));

const storeMsg = { collection: 'events', docId: p.event_id, payload: p };
if (nowMs - lastSent < cooldownMs) {
    return [null, null, storeMsg];
}

const isRainAlert = (eventCode === 'AUTO_RAIN_RETRACT' || eventCode === 'MANUAL_RAIN_WARNING');
const isHumidityAlert = (eventCode === 'HIGH_HUMIDITY_PROLONGED');
if (!isRainAlert && !isHumidityAlert) {
    return [null, null, storeMsg];
}

flow.set(cooldownKey, nowMs);
const timeStr = new Date(nowMs).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const textBody = [
    `Nhóm: ${p.group_id || 'G21_24C11'} | Thiết bị: ${p.device_id || 'esp32_01'}`,
    `Sự kiện: ${p.title_vi || eventCode}`,
    `Chi tiết: ${p.message_vi || ''}`,
    `Tổng thời gian đã phơi: ${p.formatted_time || '00:00:00'}`,
    `Thời điểm: ${timeStr}`
].join('\n');

const pushMsg = isRainAlert ? {
    method: 'POST',
    url: 'https://www.pushsafer.com/api',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    payload: {
        k: env.get('PUSHSAFER_PRIVATE_KEY') || '',
        d: 'a',
        i: '11',
        t: `AeroDry (${p.group_id || 'G21'}): ${p.title_vi}`,
        m: textBody
    }
} : null;

const emailMsg = {
    topic: `[AeroDry IoT - ${p.group_id || 'G21_24C11'}] ${p.title_vi || eventCode}`,
    payload: textBody
};

return [pushMsg, emailMsg, storeMsg];

const nowMs = Date.now();
const sinceMs = nowMs - 24 * 3600 * 1000;
const samples = (flow.get('sensor_samples_24h') || []).filter(s => s.timestamp_ms >= sinceMs);
const sessions = (flow.get('drying_sessions_24h') || []).filter(s => s.updated_at_ms >= sinceMs);
const events = (flow.get('events_24h') || []).filter(e => e.received_at_ms >= sinceMs);

msg.payload = {
    ok: true,
    has_data: samples.length > 0 || sessions.length > 0 || events.length > 0,
    chart_24h: { sample_count: samples.length, points: samples },
    session_logs: sessions,
    event_logs: events
};
return msg;
